// Field-level encryption for secure-record. Extracted verbatim (T-137, pure
// refactor — no behaviour change) from
// amplify/functions/secure-record/handler.ts:830, which now imports these
// instead of defining a second copy.
//
// KMS envelope encryption: each record gets a fresh AES-256 data key (DEK)
// generated by KMS and wrapped under the account's CMK. The wrapped key rides
// alongside the record as `__wrappedDEK`; each sensitive field is encrypted
// individually under the unwrapped DEK with AES-256-GCM (`encryptOne`), so a
// single KMS Decrypt call on read unwraps once and decrypts every field
// locally.

import { KMSClient, GenerateDataKeyCommand, DecryptCommand } from '@aws-sdk/client-kms';
import { createCipheriv, createDecipheriv, randomBytes } from 'node:crypto';

const kms = new KMSClient({});

const KMS_KEY_ID = process.env.KMS_KEY_ID!;

export const SENSITIVE_FIELDS = [
  'ssn', 'routing', 'account',
  // Names and relationships of people who are not the client. The first
  // beneficiary predates this list; the overflow blob is encrypted from the
  // start rather than inheriting that gap.
  'beneficiariesExtra',
  // cardNumber and cardCVV were here until 2026-09-07. They are gone because
  // nothing is encrypted under them any more, not merely because we stopped
  // writing them: C3a strips both at the browser and at sanitizeInput, and C3b
  // purged the historical rows and cleared the card entries out of every
  // __encryptedFields list. Verified against production before removal — no
  // record still named a card field as encrypted, so nothing is stranded
  // without a decryption path.
  //
  // The ORDER mattered and is the reason this line is a comment rather than a
  // deletion in the C3a commit. Removing a field from this list first would have
  // left the existing ciphertext unreadable — encrypted under a key the code no
  // longer knows to unwrap. Stop writing, then purge, then forget how to read.
  'conditions', 'medications',
  'dob',
  // IUL structured health screen — same PHI class as conditions/medications.
  // Encrypting these is functionally free: the live-call form's showWhen rules
  // and the underwriting advisor both read the plaintext Draft client-side, and
  // nothing queries Record by these columns server-side.
  'hxCardiac', 'hxCancer', 'hxDiabetes', 'hxBpChol', 'hxKidneyLiver',
  'hxRespiratory', 'hxMentalHealth', 'hxDementia', 'hxDui', 'hxFelony', 'hxDetails',
  // Mortgage Protection health-screen additions — same PHI class.
  'hxThyroid', 'hxAutoimmune', 'hxSurgery', 'hxSuspendedLicense',
  // Shared-checklist additions: the "Other" condition + its typed name, and the
  // two stringified-JSON blobs (per-condition diagnosis timing + selected meds).
  // All PHI — encrypted alongside the rest of the hx* screen.
  'hxOther', 'hxOtherText', 'hxTiming', 'hxMeds',
  // Underwriting Engine blobs. hxFlags carries the ~57 conditions that don't
  // have their own column, uwAnswers the structured follow-ups (A1c, insulin,
  // oxygen/CPAP, hospitalisations, prior decline), hxMonthsAgo the exact-month
  // refinements. All PHI, so all encrypted — and cheaply, since collapsing them
  // into blobs means four more encrypted fields rather than seventy.
  //
  // uwRecommendation records what the engine advised on the call. It embeds the
  // client's decision class and the rules that fired, so it's PHI too.
  // uwOutcome records what the carrier actually decided — the decision class
  // they issued at, or their decline reason, and which conditions drove it.
  // Same PHI class, and the pairing of the two is what lets a wrong rule be
  // identified from real business rather than from a document.
  'hxFlags', 'hxMonthsAgo', 'uwAnswers', 'uwRecommendation', 'uwOutcome',
  // Independent condition pills (the split of the combined conditions). Same PHI.
  'hxHeartAttack', 'hxStroke', 'hxHighBP', 'hxCholesterol', 'hxAsthma', 'hxCopd',
  'hxKidney', 'hxLiver', 'hxAnxiety', 'hxDepression', 'hxSchizophrenia',
  'hxLupus', 'hxArthritis',
  // MP identity/payment PII — encrypt the driver's-license number and the
  // card billing ZIP alongside SSN / card fields.
  'dlNumber', 'cardZip',
] as const;

export type SensitiveField = (typeof SENSITIVE_FIELDS)[number];

export function encryptOne(plaintext: string, key: Buffer): string {
  const iv = randomBytes(12);
  const cipher = createCipheriv('aes-256-gcm', key, iv);
  const ct  = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();
  return Buffer.concat([iv, tag, ct]).toString('base64');
}

export function decryptOne(b64: string, key: Buffer): string {
  const buf = Buffer.from(b64, 'base64');
  const iv  = buf.subarray(0, 12);
  const tag = buf.subarray(12, 28);
  const ct  = buf.subarray(28);
  const decipher = createDecipheriv('aes-256-gcm', key, iv);
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(ct), decipher.final()]).toString('utf8');
}

export async function encryptFields(record: Record<string, unknown>): Promise<Record<string, unknown>> {
  const present = SENSITIVE_FIELDS.filter(f => {
    const v = record[f];
    return v !== undefined && v !== null && v !== '';
  });
  if (present.length === 0) return { ...record };

  const dek = await kms.send(new GenerateDataKeyCommand({
    KeyId:   KMS_KEY_ID,
    KeySpec: 'AES_256',
  }));
  const plaintextKey = Buffer.from(dek.Plaintext!);
  const wrappedKey   = Buffer.from(dek.CiphertextBlob!);

  const out: Record<string, unknown> = { ...record };
  for (const field of present) {
    out[field] = encryptOne(String(record[field]), plaintextKey);
  }
  out.__wrappedDEK      = wrappedKey.toString('base64');
  out.__encryptedFields = present;

  plaintextKey.fill(0);
  return out;
}

export async function decryptFields(record: Record<string, unknown> | undefined | null): Promise<Record<string, unknown> | null> {
  if (!record) return null;
  const wrappedB64 = record.__wrappedDEK as string | undefined;
  const encFields  = (record.__encryptedFields as SensitiveField[] | undefined) || [];
  const out: Record<string, unknown> = { ...record };
  delete out.__wrappedDEK;
  delete out.__encryptedFields;

  if (!wrappedB64 || encFields.length === 0) return out;

  const dec = await kms.send(new DecryptCommand({
    CiphertextBlob: Buffer.from(wrappedB64, 'base64'),
    KeyId: KMS_KEY_ID,
  }));
  const plaintextKey = Buffer.from(dec.Plaintext!);

  for (const field of encFields) {
    if (typeof out[field] === 'string') {
      out[field] = decryptOne(out[field] as string, plaintextKey);
    }
  }
  plaintextKey.fill(0);
  return out;
}
